using System.Windows;
using System.Windows.Input;
using System.Windows.Controls;

namespace KOYA_APP
{
    public partial class MainWindow : Window
    {
        private IStreamDeckAction[] _buttonActions = new IStreamDeckAction[14];

        public MainWindow()
        {
            InitializeComponent();
        }

        private void OnDeckButtonClick(object sender, RoutedEventArgs e)
        {
            Button btn = (Button)sender;
            if (btn.Tag == null) return;

            if (!int.TryParse(btn.Tag.ToString(), out int index)) return;
            if (index < 0 || index >= _buttonActions.Length) return;

            if (_buttonActions[index] == null)
            {
                // Jesli index >= 12, to znaczy ze to potencjometr
                bool isAnalog = index >= 12;
                ActionPicker picker = new ActionPicker(isAnalog) { Owner = this };
                if (picker.ShowDialog() == true)
                {
                    _buttonActions[index] = picker.SelectedAction!;
                    btn.Content = _buttonActions[index].Icon;
                    btn.ToolTip = _buttonActions[index].Name;
                }
            }
            else
            {
                _buttonActions[index].Execute();
            }
        }

        private void OnKnobMouseWheel(object sender, MouseWheelEventArgs e)
        {
            Button btn = (Button)sender;
            if (btn.Tag == null) return;
            if (!int.TryParse(btn.Tag.ToString(), out int index)) return;

            if (_buttonActions[index] != null)
            {
                _buttonActions[index].ExecuteAnalog(e.Delta > 0);
            }
        }

        private void TitleBar_MouseDown(object sender, MouseButtonEventArgs e) { if (e.ChangedButton == MouseButton.Left) this.DragMove(); }
        private void Close_Click(object sender, RoutedEventArgs e) => Application.Current.Shutdown();       
        private void Minimize_Click(object sender, RoutedEventArgs e) => this.WindowState = WindowState.Minimized;
    }
}

using Microsoft.Win32;
using NAudio.CoreAudioApi;
using System.Collections.Generic;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;

namespace KOYA_APP
{
    public partial class ActionPicker : Window
    {
        public IStreamDeckAction? SelectedAction { get; set; }
        private List<byte> _capturedKeys = new List<byte>();

        public ActionPicker(bool isAnalog = false)
        {
            InitializeComponent();

            var allActions = new List<IStreamDeckAction>
            {
                new PlayPauseAction(),
                new NextTrackAction(),
                new PreviousTrackAction(),
                new VolumeAction(),
                new CopyAction(),
                new PasteAction(),
                new ScreenshotAction(),
                new TaskManagerAction(),
                new CloseWindowAction(),
                new FullscreenAction(),
                new AltTabAction(),
                new CustomShortcutAction(),
                new OpenAppAction(),
                new MuteMicrophoneAction(),
                new MuteSpeakerAction(),
                new SelectMicAction(),
                new WebZoomAction()
            };

            if (isAnalog)
            {
                // Tylko te, ktore maja sens dla pokretla
                ActionsListBox.ItemsSource = allActions.Where(a => 
                    a is VolumeAction || 
                    a is MuteMicrophoneAction || 
                    a is WebZoomAction || 
                    a is CustomShortcutAction).ToList();
            }
            else
            {
                ActionsListBox.ItemsSource = allActions;
            }
        }

        private void ActionsListBox_SelectionChanged(object sender, SelectionChangedEventArgs e)
        {
            var selected = ActionsListBox.SelectedItem as IStreamDeckAction;
            ExtraSettingsPanel.Visibility = Visibility.Collapsed;
            DevicesComboBox.Visibility = Visibility.Collapsed;
            ShortcutTextBox.Visibility = Visibility.Collapsed;

            if (selected is SelectMicAction)
            {
                ExtraSettingsPanel.Visibility = Visibility.Visible;
                DevicesComboBox.Visibility = Visibility.Visible;
                ExtraSettingsTitle.Text = "Wybierz urzadzenie wejsciowe (Mikrofon):";
                var enumerator = new MMDeviceEnumerator();
                var devices = enumerator.EnumerateAudioEndPoints(DataFlow.Capture, DeviceState.Active).ToList();
                DevicesComboBox.ItemsSource = devices;
                if (devices.Count > 0) DevicesComboBox.SelectedIndex = 0;
            }
            else if (selected is CustomShortcutAction)
            {
                ExtraSettingsPanel.Visibility = Visibility.Visible;
                ShortcutTextBox.Visibility = Visibility.Visible;
                ExtraSettingsTitle.Text = "Wcisnij kombinacje klawiszy:";
                _capturedKeys.Clear();
                ShortcutTextBox.Text = "Kliknij tutaj i wcisnij klawisze...";
            }
        }

        private void ShortcutTextBox_PreviewKeyDown(object sender, KeyEventArgs e)
        {
            e.Handled = true;
            int vk = KeyInterop.VirtualKeyFromKey(e.Key);
            if (vk == 0) return;
            byte vkByte = (byte)vk;
            if (!_capturedKeys.Contains(vkByte)) _capturedKeys.Add(vkByte);
            List<string> keyNames = _capturedKeys.Select(k => ((Key)KeyInterop.KeyFromVirtualKey(k)).ToString()).ToList();
            ShortcutTextBox.Text = string.Join(" + ", keyNames);
        }

        private void Select_Click(object sender, RoutedEventArgs e)
        {
            var selected = ActionsListBox.SelectedItem as IStreamDeckAction;
            if (selected == null) return;

            if (selected is OpenAppAction appAction)
            {
                OpenFileDialog ofd = new OpenFileDialog { Filter = "Aplikacje (*.exe)|*.exe" };
                if (ofd.ShowDialog() == true) { appAction.Path = ofd.FileName; SelectedAction = appAction; }
            }
            else if (selected is CustomShortcutAction shortcutAction)
            {
                if (_capturedKeys.Count > 0) { shortcutAction.KeyCodes = new List<byte>(_capturedKeys); shortcutAction.KeysDisplay = ShortcutTextBox.Text; SelectedAction = shortcutAction; }
            }
            else if (selected is SelectMicAction micAction)
            {
                var device = DevicesComboBox.SelectedItem as MMDevice;
                if (device != null) { micAction.DeviceID = device.ID; micAction.DeviceName = device.FriendlyName; SelectedAction = micAction; }
            }
            else { SelectedAction = selected; }

            if (SelectedAction != null) { this.DialogResult = true; this.Close(); }
        }

        private void Cancel_Click(object sender, RoutedEventArgs e) => this.Close();
    }
}

namespace KOYA_APP
{
    public interface IStreamDeckAction
    {
        string Name { get; }
        string Description { get; }
        string Icon { get; }
        void Execute(); // Dla klikniecia
        void ExecuteAnalog(bool direction); // true = w prawo / glosniej, false = w lewo / ciszej
    }
}

using System.Runtime.InteropServices;

namespace KOYA_APP
{
    public class VolumeAction : IStreamDeckAction
    {
        public string Name => "VOLUME";
        public string Icon => "\uE15D";
        public string Description => "Main System Volume";

        public void Execute() { keybd_event(0xAD, 0, 0, 0); keybd_event(0xAD, 0, 2, 0); }
        public void ExecuteAnalog(bool direction) { byte vk = direction ? (byte)0xAF : (byte)0xAE; keybd_event(vk, 0, 0, 0); keybd_event(vk, 0, 2, 0); }

        [DllImport("user32.dll")] private static extern void keybd_event(byte bVk, byte bScan, uint dwFlags, int dwExtraInfo);
    }
}

using NAudio.CoreAudioApi;

namespace KOYA_APP
{
    public class MuteMicrophoneAction : IStreamDeckAction
    {
        public string Name => "MIC MUTE";
        public string Icon => "\uE1D6";
        public string Description => "Toggle Microphone";

        public void Execute() { try { var en = new MMDeviceEnumerator(); var d = en.GetDefaultAudioEndpoint(DataFlow.Capture, Role.Communications); d.AudioEndpointVolume.Mute = !d.AudioEndpointVolume.Mute; } catch {} }
        public void ExecuteAnalog(bool direction) { try { var en = new MMDeviceEnumerator(); var d = en.GetDefaultAudioEndpoint(DataFlow.Capture, Role.Communications); float step = 0.05f; float cur = d.AudioEndpointVolume.MasterVolumeLevelScalar; d.AudioEndpointVolume.MasterVolumeLevelScalar = direction ? System.Math.Min(1f, cur + step) : System.Math.Max(0f, cur - step); } catch {} }
    }
}

